import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJFGRv8Z.js";var i=JSON.parse(`{"title":"发信与投递","description":"","frontmatter":{},"headers":[],"relativePath":"guide/sending-delivery.md","filePath":"guide/sending-delivery.md","lastUpdated":1788621106000}`),a={name:`guide/sending-delivery.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="发信与投递" tabindex="-1">发信与投递 <a class="header-anchor" href="#发信与投递" aria-label="Permalink to “发信与投递”">​</a></h1><h2 id="发信资格" tabindex="-1">发信资格 <a class="header-anchor" href="#发信资格" aria-label="Permalink to “发信资格”">​</a></h2><p>能否发信由邮箱状态、所属域名、套餐配额和平台策略共同决定。部分域名需要管理员先批准域名发信，再批准用户或邮箱的发信申请。</p><p>在发信设置中可以查看当前资格、剩余额度和申请状态。审核未通过时，请按页面提示补充用途，避免重复提交相同申请。</p><h2 id="投递通道" tabindex="-1">投递通道 <a class="header-anchor" href="#投递通道" aria-label="Permalink to “投递通道”">​</a></h2><p>平台可按域名选择直接 MX 投递或外部中继。管理员负责配置 DKIM、HELO、退信处理和中继凭据；普通用户无需填写这些系统参数。</p><p>发送前会进行地址格式、域名和策略检查。被黑名单或抑制名单命中的收件人会被阻止，以避免持续向无效地址投递。</p><h2 id="投递状态" tabindex="-1">投递状态 <a class="header-anchor" href="#投递状态" aria-label="Permalink to “投递状态”">​</a></h2><p>已发送不等于已送达。常见结果包括：</p><table tabindex="0"><thead><tr><th>状态</th><th>含义</th><th>建议</th></tr></thead><tbody><tr><td>排队</td><td>正等待投递</td><td>稍后刷新，不要重复发送</td></tr><tr><td>已投递</td><td>对方服务器已接受</td><td>最终是否进收件箱由对方判断</td></tr><tr><td>临时失败</td><td>网络或对方服务暂时不可用</td><td>等待系统重试</td></tr><tr><td>永久失败</td><td>地址、策略或域名被拒绝</td><td>查看原因后修正地址或联系管理员</td></tr><tr><td>被抑制</td><td>收件人被安全策略拦截</td><td>管理员确认原因后处理</td></tr></tbody></table><h2 id="提高送达率" tabindex="-1">提高送达率 <a class="header-anchor" href="#提高送达率" aria-label="Permalink to “提高送达率”">​</a></h2><ul><li>使用真实、稳定的发件身份和清晰主题。</li><li>只给同意接收邮件的地址发信，并及时处理退订和无效地址。</li><li>避免短时间内突然增加发信量。</li><li>不发送可执行附件、欺骗性链接或重复垃圾内容。</li></ul><h2 id="dkim、spf-与-dmarc" tabindex="-1">DKIM、SPF 与 DMARC <a class="header-anchor" href="#dkim、spf-与-dmarc" aria-label="Permalink to “DKIM、SPF 与 DMARC”">​</a></h2><p>自有域名应同时设置 DKIM、SPF 和 DMARC。DNS 检查通过只代表记录可读取；修改 DNS 后仍需等待全球缓存刷新。管理员可在域名页面重新检查并查看具体缺失项。</p>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};